using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Infrastructure;
using Microsoft.EntityFrameworkCore.Migrations;
using Microsoft.EntityFrameworkCore.Migrations.Operations;

#pragma warning disable CA2100 // SQL is generated by EF from constant migration operations.

namespace Cratis.Chronicle.Storage.Sql.EventStores.Namespaces.ReadModels.for_ReadModelMigrator;

public class when_generating_sqlite_virtual_columns : Specification
{
    SqliteConnection _connection;
    string _createSql;
    string _addSql;
    string _indexedColumn;
    long _virtualColumns;

    void Establish()
    {
        _connection = new SqliteConnection("Data Source=:memory:");
        _connection.Open();
    }

    void Because()
    {
        using var context = new DbContext(new DbContextOptionsBuilder().UseSqlite(_connection).Options);
        var generator = context.GetService<IMigrationsSqlGenerator>();
        var create = new CreateTableOperation { Name = "decimals" };
        create.Columns.Add(new AddColumnOperation { Table = "decimals", Name = "amount", ClrType = typeof(string), ColumnType = "TEXT" });
        create.Columns.Add(Column("first"));
        _createSql = generator.Generate([create]).Single().CommandText;
        _addSql = generator.Generate([Column("second")]).Single().CommandText;
        using var command = _connection.CreateCommand();
        command.CommandText = _createSql + _addSql + "CREATE INDEX decimal_order ON decimals(second);";
        command.ExecuteNonQuery();
        command.CommandText = "SELECT count(*) FROM pragma_table_xinfo('decimals') WHERE hidden=2";
        _virtualColumns = (long)command.ExecuteScalar()!;
        command.CommandText = "SELECT name FROM pragma_index_info('decimal_order')";
        _indexedColumn = (string)command.ExecuteScalar()!;
    }

    void Destroy() => _connection.Dispose();

    static AddColumnOperation Column(string name) => new()
    {
        Table = "decimals", Name = name, ClrType = typeof(string), ColumnType = "TEXT",
        IsNullable = true, ComputedColumnSql = "'1' || amount", IsStored = false
    };

    [Fact] void should_emit_a_computed_column_in_create_table() => _createSql.ShouldContain("AS ('1' || amount)");
    [Fact] void should_emit_a_computed_column_in_add_column() => _addSql.ShouldContain("AS ('1' || amount)");
    [Fact] void should_create_both_columns_as_virtual() => _virtualColumns.ShouldEqual(2);
    [Fact] void should_report_the_generated_column_name_in_index_info() => _indexedColumn.ShouldEqual("second");
}
